#!/usr/bin/env python3
"""Generate the shared typed calibration codec from the retained own003 layout."""
import sys
from pathlib import Path
R=Path(__file__).resolve().parents[1];sys.path.insert(0,str(R/'tools'))
from engine_protocol_legacy import NUMBERS,FLAGS,CURVES,REVISION_OFFSET,TIMING_FIELDS
from idle_config import SCALARS as IDLE_SCALARS,ARRAYS as IDLE_ARRAYS,SCALAR_OFFSETS,ARRAY_OFFSETS,USED_END
from transient_config import SCALARS as AE_SCALARS,ARRAYS as AE_ARRAYS,SCALAR_OFFSETS as AE_SCALAR_OFFSETS,ARRAY_OFFSETS as AE_ARRAY_OFFSETS,USED_END as AE_USED_END
from load_config import ENUM_FIELDS as LOAD_ENUM_FIELDS,SCALARS as LOAD_SCALARS,ENUM_OFFSETS as LOAD_ENUM_OFFSETS,SCALAR_OFFSETS as LOAD_SCALAR_OFFSETS,ENUMS as LOAD_ENUMS,CPP_ENUMS as LOAD_CPP_ENUMS,OFFSET as LOAD_OFFSET,USED_END as LOAD_USED_END
from secondary_config import KINDS,ENUM_FIELDS as SEC_ENUM_FIELDS,SCALARS as SEC_SCALARS,ENUMS as SEC_ENUMS,CPP_ENUMS as SEC_CPP_ENUMS,OFFSET as SEC_OFFSET,CONTROL_END as SEC_CONTROL_END,MAP_OFFSETS as SEC_MAP_OFFSETS,USED_END as SEC_USED_END,rule_offset,enum_offset,scalar_offset
from flex_config import PAGE_BYTES,LIVE_BYTES,USED_END as FLEX_USED_END,BOOLEANS as FLEX_BOOLEANS,CAPTURE_FLOATS as FLEX_FLOATS,ARRAYS as FLEX_ARRAYS,OFFSETS as FLEX_OFFSETS,cpp as flex_cpp
out=['// Generated by scripts/generate_tuning_wire.py. Preserve historical own003 offsets.', '#pragma once','#include "ecu/engine.hpp"','#include <array>','#include <cstring>','#include <limits>','namespace ecu::tuning {',
 f'inline constexpr std::size_t page_bytes={PAGE_BYTES},live_bytes={LIVE_BYTES},chunk_bytes=256;',
 'inline constexpr const char signature[]="ESP32ECU DEV 010 INHIBITED";',
 'inline constexpr const char serial_protocol[]="002";',
 'using Page=std::array<std::uint8_t,page_bytes>;',
 'inline void put_u32(std::uint8_t*p,std::uint32_t v){for(unsigned i=0;i<4;++i)p[i]=std::uint8_t(v>>(8*i));}',
 'inline std::uint32_t get_u32(const std::uint8_t*p){std::uint32_t v=0;for(unsigned i=0;i<4;++i)v|=std::uint32_t(p[i])<<(8*i);return v;}',
 'inline void put_float(std::uint8_t*p,float v){static_assert(sizeof(float)==4&&std::numeric_limits<float>::is_iec559);std::uint32_t u;std::memcpy(&u,&v,4);put_u32(p,u);}',
 'inline float get_float(const std::uint8_t*p){auto u=get_u32(p);float v;std::memcpy(&v,&u,4);return v;}',
 f'inline bool reserved_offset(std::size_t n){{return (n>=292&&n<512)||(n>=4756&&n<4768)||(n>={USED_END}&&n<4992)||(n>={AE_USED_END}&&n<{LOAD_OFFSET})||(n>={LOAD_USED_END}&&n<{SEC_OFFSET})||(n>={SEC_CONTROL_END}&&n<{SEC_MAP_OFFSETS["fuel"]})||n>={FLEX_USED_END};}}',
 'inline bool revision_offset(std::size_t n){return n>=268&&n<272;}',
 '// own010 appends flex capture/correction settings without moving old fields.',
 'inline bool representable(const engine::Tune&t){return !engine::validate(t);}',
 'inline void encode_page(const engine::Tune&t,std::uint32_t origin,Page&p){p.fill(0);']
out.append(' put_u32(p.data(),'+ '|'.join('(std::uint32_t(t.'+k+')<<'+str(i)+')' for i,k in enumerate(FLAGS))+');')
for i,(_,k) in enumerate(NUMBERS):out.append(f' put_float(p.data()+{4+4*i},t.{k});')
offset=4+4*len(NUMBERS)
for k,n in CURVES:out.append(f' for(unsigned i=0;i<{n};++i)put_float(p.data()+{offset}+i*4,t.{k}[i]);');offset+=n*4
assert offset==REVISION_OFFSET
out+=[' put_u32(p.data()+268,origin);',' put_u32(p.data()+272,std::uint32_t(t.strategy));']
for k,offset in TIMING_FIELDS:out.append(f' put_float(p.data()+{offset},t.{k});')
out.append(' for(unsigned i=0;i<4;++i)p[288+i]=t.firing_order[i];')
for k,offset in [('ve',512),('spark',1664),('lambda',2816)]:
 out += [f' for(unsigned i=0;i<16;++i){{put_float(p.data()+{offset}+i*4,t.{k}.rpm[i]);put_float(p.data()+{offset+64}+i*4,t.{k}.load[i]);}}',f' for(unsigned i=0;i<256;++i)put_float(p.data()+{offset+128}+i*4,t.{k}.cells[i]);']
out += [' for(unsigned c=0;c<4;++c){const auto&m=t.cylinder_fuel[c];const auto o=3968+c*192;', '  for(unsigned i=0;i<6;++i){put_float(p.data()+o+i*4,m.rpm[i]);put_float(p.data()+o+24+i*4,m.load[i]);}', '  for(unsigned i=0;i<36;++i){put_float(p.data()+o+48+i*4,m.cells[i]);}put_float(p.data()+4736+c*4,t.cylinder_spark_deg[c]);}', ' put_u32(p.data()+4752,t.cylinder_trims_enabled);',' put_u32(p.data()+4768,std::uint32_t(t.idle_control.algorithm));']
for k in IDLE_SCALARS:out.append(f' put_float(p.data()+{SCALAR_OFFSETS[k]},t.idle_control.{k});')
for k,n in IDLE_ARRAYS:out.append(f' for(unsigned i=0;i<{n};++i)put_float(p.data()+{ARRAY_OFFSETS[k]}+i*4,t.idle_control.{k}[i]);')
out += [' put_u32(p.data()+4992,std::uint32_t(t.transient_enrichment.mode));put_u32(p.data()+4996,std::uint32_t(t.transient_enrichment.apply));']
for k in AE_SCALARS:out.append(f' put_float(p.data()+{AE_SCALAR_OFFSETS[k]},t.transient_enrichment.{k});')
for k in AE_ARRAYS:out.append(f' for(unsigned i=0;i<4;++i)put_float(p.data()+{AE_ARRAY_OFFSETS[k]}+i*4,t.transient_enrichment.{k}[i]);')
for k in LOAD_ENUM_FIELDS:out.append(f' put_u32(p.data()+{LOAD_ENUM_OFFSETS[k]},std::uint32_t(t.load_model.{k}));')
for k in LOAD_SCALARS:out.append(f' put_float(p.data()+{LOAD_SCALAR_OFFSETS[k]},t.load_model.{k});')
for kind in KINDS:
 for k in SEC_ENUM_FIELDS:out.append(f' put_u32(p.data()+{enum_offset(kind,k)},std::uint32_t(t.secondary_tables.{kind}.{k}));')
 for k in SEC_SCALARS:out.append(f' put_float(p.data()+{scalar_offset(kind,k)},t.secondary_tables.{kind}.{k});')
 out.append(f' put_u32(p.data()+{rule_offset(kind)+28},t.secondary_tables.{kind}.input_channel);put_u32(p.data()+{rule_offset(kind)+32},t.secondary_tables.{kind}.active_high);')
 key='secondary_ve' if kind=='fuel' else 'secondary_spark';offset=SEC_MAP_OFFSETS[kind]
 out += [f' for(unsigned i=0;i<16;++i){{put_float(p.data()+{offset}+i*4,t.{key}.rpm[i]);put_float(p.data()+{offset+64}+i*4,t.{key}.load[i]);}}',f' for(unsigned i=0;i<256;++i)put_float(p.data()+{offset+128}+i*4,t.{key}.cells[i]);']
for name in (*FLEX_BOOLEANS,'cycles'):out.append(f' put_u32(p.data()+{FLEX_OFFSETS[name]},{flex_cpp(name)});')
for name in FLEX_FLOATS:out.append(f' put_float(p.data()+{FLEX_OFFSETS[name]},{flex_cpp(name)});')
for name in FLEX_ARRAYS:out.append(f' for(unsigned i=0;i<6;++i)put_float(p.data()+{FLEX_OFFSETS[name]}+i*4,{flex_cpp(name)}[i]);')
out += ['}',
 'inline bool decode_page(const Page&p,std::uint32_t origin,engine::Tune&t){', ' if(!origin||get_u32(p.data()+268)!=origin)return false;', ' for(unsigned n=0;n<page_bytes;++n)if(reserved_offset(n)&&p[n])return false;',f' const auto flags=get_u32(p.data());if(flags>>{len(FLAGS)})return false;']
for i,k in enumerate(FLAGS):out.append(f' t.{k}=flags&(1U<<{i});')
for i,(_,k) in enumerate(NUMBERS):
 if k=='cylinders':out.append(f' if(get_float(p.data()+{4+4*i})!=4){{return false;}}t.cylinders=4;')
 else:out.append(f' t.{k}=get_float(p.data()+{4+4*i});')
offset=4+4*len(NUMBERS)
for k,n in CURVES:out.append(f' for(unsigned i=0;i<{n};++i)t.{k}[i]=get_float(p.data()+{offset}+i*4);');offset+=n*4
out += [' t.revision=origin;const auto strategy=get_u32(p.data()+272);if(strategy>2)return false;t.strategy=engine::Strategy(strategy);']
for k,offset in TIMING_FIELDS:out.append(f' t.{k}=get_float(p.data()+{offset});')
out.append(' for(unsigned i=0;i<4;++i)t.firing_order[i]=p[288+i];')
for k,offset in [('ve',512),('spark',1664),('lambda',2816)]:
 out += [f' for(unsigned i=0;i<16;++i){{t.{k}.rpm[i]=get_float(p.data()+{offset}+i*4);t.{k}.load[i]=get_float(p.data()+{offset+64}+i*4);}}',f' for(unsigned i=0;i<256;++i)t.{k}.cells[i]=get_float(p.data()+{offset+128}+i*4);']
out += [' for(unsigned c=0;c<4;++c){auto&m=t.cylinder_fuel[c];const auto o=3968+c*192;', '  for(unsigned i=0;i<6;++i){m.rpm[i]=get_float(p.data()+o+i*4);m.load[i]=get_float(p.data()+o+24+i*4);}', '  for(unsigned i=0;i<36;++i){m.cells[i]=get_float(p.data()+o+48+i*4);}t.cylinder_spark_deg[c]=get_float(p.data()+4736+c*4);}', ' const auto enabled=get_u32(p.data()+4752);if(enabled>1)return false;t.cylinder_trims_enabled=enabled;', ' const auto idle_algorithm=get_u32(p.data()+4768);if(idle_algorithm>2)return false;t.idle_control.algorithm=idle::Algorithm(idle_algorithm);']
for k in IDLE_SCALARS:out.append(f' t.idle_control.{k}=get_float(p.data()+{SCALAR_OFFSETS[k]});')
for k,n in IDLE_ARRAYS:out.append(f' for(unsigned i=0;i<{n};++i)t.idle_control.{k}[i]=get_float(p.data()+{ARRAY_OFFSETS[k]}+i*4);')
out += [' const auto ae_mode=get_u32(p.data()+4992),ae_apply=get_u32(p.data()+4996);if(ae_mode>3||ae_apply>1)return false;t.transient_enrichment.mode=transient::Mode(ae_mode);t.transient_enrichment.apply=transient::Apply(ae_apply);']
for k in AE_SCALARS:out.append(f' t.transient_enrichment.{k}=get_float(p.data()+{AE_SCALAR_OFFSETS[k]});')
for k in AE_ARRAYS:out.append(f' for(unsigned i=0;i<4;++i)t.transient_enrichment.{k}[i]=get_float(p.data()+{AE_ARRAY_OFFSETS[k]}+i*4);')
for k in LOAD_ENUM_FIELDS:out.append(f' const auto load_{k}=get_u32(p.data()+{LOAD_ENUM_OFFSETS[k]});if(load_{k}>={len(LOAD_ENUMS[k])})return false;t.load_model.{k}=load::{LOAD_CPP_ENUMS[k]}(load_{k});')
for k in LOAD_SCALARS:out.append(f' t.load_model.{k}=get_float(p.data()+{LOAD_SCALAR_OFFSETS[k]});')
for kind in KINDS:
 for k in SEC_ENUM_FIELDS:
  cpp=SEC_CPP_ENUMS[k] if k in ('source','axis') else 'secondary::'+SEC_CPP_ENUMS[k]
  out.append(f' const auto sec_{kind}_{k}=get_u32(p.data()+{enum_offset(kind,k)});if(sec_{kind}_{k}>={len(SEC_ENUMS[k])})return false;t.secondary_tables.{kind}.{k}={cpp}(sec_{kind}_{k});')
 for k in SEC_SCALARS:out.append(f' t.secondary_tables.{kind}.{k}=get_float(p.data()+{scalar_offset(kind,k)});')
 out.append(f' const auto sec_{kind}_channel=get_u32(p.data()+{rule_offset(kind)+28}),sec_{kind}_polarity=get_u32(p.data()+{rule_offset(kind)+32});if(sec_{kind}_channel>1||sec_{kind}_polarity>1)return false;t.secondary_tables.{kind}.input_channel=std::uint8_t(sec_{kind}_channel);t.secondary_tables.{kind}.active_high=sec_{kind}_polarity;')
 key='secondary_ve' if kind=='fuel' else 'secondary_spark';offset=SEC_MAP_OFFSETS[kind]
 out += [f' for(unsigned i=0;i<16;++i){{t.{key}.rpm[i]=get_float(p.data()+{offset}+i*4);t.{key}.load[i]=get_float(p.data()+{offset+64}+i*4);}}',f' for(unsigned i=0;i<256;++i)t.{key}.cells[i]=get_float(p.data()+{offset+128}+i*4);']
for name in FLEX_BOOLEANS:out.append(f' const auto flex_{name}=get_u32(p.data()+{FLEX_OFFSETS[name]});if(flex_{name}>1)return false;{flex_cpp(name)}=flex_{name};')
out.append(f' const auto flex_cycles=get_u32(p.data()+{FLEX_OFFSETS["cycles"]});if(flex_cycles<2||flex_cycles>32)return false;t.flex_fuel.capture.cycles=static_cast<std::uint8_t>(flex_cycles);')
for name in FLEX_FLOATS:out.append(f' {flex_cpp(name)}=get_float(p.data()+{FLEX_OFFSETS[name]});')
for name in FLEX_ARRAYS:out.append(f' for(unsigned i=0;i<6;++i){flex_cpp(name)}[i]=get_float(p.data()+{FLEX_OFFSETS[name]}+i*4);')
out += [' return !engine::validate(t);','}',
 '// Update only an owned, already canonical schema9 tree. No global data mutates.', 'template<class Json> bool update_document(Json&j,const engine::Tune&t){', ' if(!j.header(t.revision,engine::strategy_name(t.strategy)))return false;']
for group,k in NUMBERS:out.append(f' if(!j.number("{group}","{k}",t.{k}))return false;')
for k in FLAGS:out.append(f' if(!j.boolean("settings","{k}",t.{k}))return false;')
for k,n in CURVES:out.append(f' if(!j.array("curves","{k}",t.{k}))return false;')
for k in ['ve','spark','lambda']:out.append(f' if(!j.map("{k}",t.{k}))return false;')
for k,_ in TIMING_FIELDS:out.append(f' if(!j.number("timing","{k}",t.{k}))return false;')
out += [' if(!j.array("timing","firing_order",t.firing_order)||!j.boolean("cylinder_trims","enabled",t.cylinder_trims_enabled)||!j.array("cylinder_trims","spark_deg",t.cylinder_spark_deg))return false;', ' for(unsigned i=0;i<4;++i)if(!j.trim(i,t.cylinder_fuel[i]))return false;', ' if(!j.idle(t.idle_control)||!j.transient_enrichment(t.transient_enrichment)||!j.load_model(t.load_model)||!j.secondary_tables(t.secondary_tables,t.secondary_ve,t.secondary_spark)||!j.flex_fuel(t.flex_fuel))return false;',' return true;','}','} // namespace ecu::tuning']
(R/'firmware/include/ecu/tuning_layout.hpp').write_text('\n'.join(out)+'\n')
print('Generated shared own010 single-page typed codec')
